BEGIN;

TRUNCATE TABLE project_college_link;

INSERT INTO project_college_link (project_id, college_name)
SELECT DISTINCT
  p.id,
  cm.college_name
FROM projects p
JOIN college_map cm
  ON p.exec_unit IS NOT NULL
 AND p.exec_unit ~ cm.pattern;

COMMIT;

