let sourceData;
try {
  sourceData = $items("If").map(i => i.json);
} catch (e) {
  try {
    sourceData = $items("Normalize Project Data").map(i => i.json);
  } catch (e2) {
    sourceData = $items("Code in JavaScript").map(i => i.json);
  }
}

let text = items[0].json.content?.parts?.[0]?.text || items[0].json.text || "";
text = text.replace(/```json|```/g, "").trim();
let parsed;
try {
  parsed = JSON.parse(text);
} catch (err) {
  throw new Error("無法解析 AI 回傳的 JSON，請檢查格式。");
}

const map = {};
for (const row of parsed) {
  const id = row.id || row.ID || row.Id;
  const label = row["分類"] || row["類別"] || row["category"] || "";
  if (id != null) map[id] = label.trim();
}

const combined = sourceData.map((r, idx) => ({
  json: {
    ...r,
    unit_category: map[idx + 1] || "其他"
  }
}));
return combined;

const roc = (v) => {
  if (!v || !v.trim()) return null;
  const s = v.trim();
  const y = parseInt(s.substring(0, 3)) + 1911;
  const m = s.substring(3, 5);
  const d = s.substring(5, 7);
  return `${y}-${m}-${d}`;
};

const N = (v) => {
  const n = Number(v);
  return isNaN(n) ? 0 : n;
};

return items.map(item => {
  const r = item.json;
  return {
    json: {
      project_code: r["BUGETNO"]?.trim(),
      project_name:      r["BUGNAME"],
      exec_unit:         r["DEPNAME"],
      fund_source:       r["PRODEPNAME"],
      pi_code:           r["LEADER"],
      start_date:        roc(r["START"]),
      end_date:          roc(r["DEADLINE"]),
      extend_date_raw:   roc(r["DELAY"]),
      close_date:        roc(r["CLOSED"]),
      approve_amount:    N(r["AMOUNT"]),
      received_amount:   N(r["INCOME"]),
      spent_amount:      N(r["EXPENSE"]),
      refund_amount_raw: r["RETURNAMOUNT"],
      manage_fee:        N(r["MANAGEAMOUNT"]),
    }
  };
});

const dateOnly = (v) => {
  if (!v) return "";
  return String(v).substring(0, 10);
};

const existing = {};
for (const i of $items("Fetch Existing Projects")) {
  existing[i.json.project_code?.trim()] = i.json;
}

const incoming = $items("Code in JavaScript").map(i => i.json);

const results = [];

for (const r of incoming) {
  const code = r.project_code?.trim();
  const old = existing[code];

  if (!old) {
    results.push({ json: { ...r, _route: "new" } });
  } else if (
    Number(old.approve_amount) !== Number(r.approve_amount) ||
    Number(old.received_amount) !== Number(r.received_amount) ||
    Number(old.spent_amount) !== Number(r.spent_amount) ||
    dateOnly(old.close_date) !== dateOnly(r.close_date)
  ) {
    results.push({ json: { ...r, _route: "update", unit_category: old.unit_category } });
  }
}

return results;
